// common/speculative.h
//
// This file defines the main speculative decoding infrastructure for llama.cpp.
//
// The core idea: run a small "draft" model in parallel with the main "target" model.
// The draft model proposes a sequence of tokens (a "draft" sequence).
 The target model verifies the entire sequence at once (parallel verification).
 If the longest prefix of the tokens matches what the target would have produced,
 the target accepts that prefix and continues from there.
